1	// Normalisers used for duplicate detection and junk-host checks.
2	// Pure string helpers: no network, no throwing.
3	
4	const PROTOCOL = /^[a-z][a-z0-9+.-]*:\/\//;
5	
6	// Lowercased host only: no protocol, "www.", port, path, query, hash,
7	// trailing slash or trailing dot. Returns "" when nothing is left.
8	export function normalizeDomain(input: string): string {
9	  let s = String(input ?? "").trim().toLowerCase();
10	  s = s.replace(PROTOCOL, "");
11	  s = s.split(/[/?#]/)[0] ?? "";
12	  s = s.replace(/^[^@]*@/, ""); // user:pass@host
13	  s = s.replace(/:\d+$/, ""); // port
14	  s = s.replace(/^www\./, "");
15	  s = s.replace(/\.+$/, "");
16	  return s;
17	}
18	
19	// Lowercased LinkedIn URL without protocol, "www.", query, hash or trailing
20	// slash. Returns "" when nothing is left.
21	export function normalizeLinkedInUrl(input: string): string {
22	  let s = String(input ?? "").trim().toLowerCase();
23	  s = s.replace(PROTOCOL, "");
24	  s = s.replace(/^www\./, "");
25	  s = s.split(/[?#]/)[0] ?? "";
26	  s = s.replace(/\/+$/, "");
27	  return s;
28	}
