1	// Code-rule validation of raw companies. Pure and deterministic: the same
2	// input always gives the same output, and no rule ever throws.
3	
4	import type {
5	  RawCompany,
6	  Validation,
7	  ValidationIssue,
8	  ValidationStatus,
9	} from "../types";
10	import { normalizeDomain, normalizeLinkedInUrl } from "./normalize";
11	
12	// Hosts that are messaging, link-shortener or social pages, not real sites.
13	export const JUNK_HOSTS: readonly string[] = [
14	  "wa.link",
15	  "wa.me",
16	  "bit.ly",
17	  "linktr.ee",
18	  "facebook.com",
19	  "instagram.com",
20	  "t.me",
21	];
22	
23	// Above this implied revenue per employee (USD) the data is not believable.
24	export const MAX_REVENUE_PER_EMPLOYEE_USD = 500000;
25	
26	interface Range {
27	  readonly min: number;
28	  readonly max: number; // Infinity for open-ended ranges like "10,001+"
29	}
30	
31	function toNumber(text: string): number | undefined {
32	  const n = Number(text.replace(/,/g, ""));
33	  return Number.isFinite(n) ? n : undefined;
34	}
35	
36	// "51-200" -> {51, 200}; "10,001+" -> {10001, Infinity}; else undefined.
37	export function parseEmployeeRange(input: unknown): Range | undefined {
38	  if (typeof input !== "string") return undefined;
39	  const s = input.trim();
40	  const span = /^(\d[\d,]*)\s*[-–]\s*(\d[\d,]*)$/.exec(s);
41	  if (span) {
42	    const min = toNumber(span[1]);
43	    const max = toNumber(span[2]);
44	    if (min === undefined || max === undefined || max < min) return undefined;
45	    return { min, max };
46	  }
47	  const open = /^(\d[\d,]*)\s*\+$/.exec(s);
48	  if (open) {
49	    const min = toNumber(open[1]);
50	    return min === undefined ? undefined : { min, max: Infinity };
51	  }
52	  return undefined;
53	}
54	
55	const SUFFIX: Readonly<Record<string, number>> = {
56	  "": 1,
57	  k: 1e3,
58	  m: 1e6,
59	  b: 1e9,
60	};
61	
62	// Lower bound in USD of a range like "$10M-$50M", "$500K-$1M" or "$10M+".
63	// Undefined for anything else (e.g. "<$1M", "unknown").
64	export function parseRevenueLowerBound(input: unknown): number | undefined {
65	  if (typeof input !== "string") return undefined;
66	  const m = /^\$?\s*(\d[\d,]*(?:\.\d+)?)\s*([kmb]?)\s*(?:[-–]|to\b|\+|$)/i.exec(
67	    input.trim(),
68	  );
69	  if (!m) return undefined;
70	  const base = toNumber(m[1]);
71	  if (base === undefined) return undefined;
72	  return base * (SUFFIX[m[2].toLowerCase()] ?? 1);
73	}
74	
75	function isEmpty(value: unknown): boolean {
76	  return typeof value !== "string" || value.trim() === "";
77	}
78	
79	function isJunkHost(host: string): boolean {
80	  return JUNK_HOSTS.some((j) => host === j || host.endsWith(`.${j}`));
81	}
82	
83	// Key used to group duplicates: domain first, LinkedIn URL when no domain.
84	function duplicateKey(raw: RawCompany): string | undefined {
85	  const domain = normalizeDomain(raw.primary_domain);
86	  if (domain) return `domain:${domain}`;
87	  const linkedin = normalizeLinkedInUrl(raw.professional_network_url);
88	  if (linkedin) return `linkedin:${linkedin}`;
89	  return undefined;
90	}
91	
92	function sizeIssues(raw: RawCompany): ValidationIssue[] {
93	  const issues: ValidationIssue[] = [];
94	  const headcount = raw.latest_headcount;
95	  if (
96	    typeof headcount !== "number" ||
97	    !Number.isFinite(headcount) ||
98	    headcount <= 0
99	  ) {
100	    return issues;
101	  }
102	
103	  const range = parseEmployeeRange(raw.employee_count_range);
104	  if (range && (headcount < range.min || headcount > range.max)) {
105	    issues.push({
106	      code: "size_headcount_mismatch",
107	      field: "latest_headcount",
108	      reason: `Headcount ${headcount} is outside the listed size range "${raw.employee_count_range}".`,
109	    });
110	  }
111	
112	  const revenueMin = parseRevenueLowerBound(raw.revenue_range);
113	  if (
114	    revenueMin !== undefined &&
115	    revenueMin / headcount > MAX_REVENUE_PER_EMPLOYEE_USD
116	  ) {
117	    issues.push({
118	      code: "size_headcount_mismatch",
119	      field: "revenue_range",
120	      reason: `Revenue "${raw.revenue_range}" with ${headcount} employees implies more than $${MAX_REVENUE_PER_EMPLOYEE_USD.toLocaleString("en-US")} per employee, which is implausible.`,
121	    });
122	  }
123	  return issues;
124	}
125	
126	export function validateCompanies(
127	  raws: readonly RawCompany[],
128	): readonly Validation[] {
129	  const firstSeen = new Map<string, number>(); // key -> crustdata_company_id
130	
131	  return raws.map((raw): Validation => {
132	    const issues: ValidationIssue[] = [];
133	
134	    const noName = isEmpty(raw.name);
135	    const domain = normalizeDomain(raw.primary_domain ?? "");
136	    const linkedin = normalizeLinkedInUrl(raw.professional_network_url ?? "");
137	
138	    if (noName) {
139	      issues.push({
140	        code: "missing_name",
141	        field: "name",
142	        reason: "The company has no name.",
143	      });
144	    }
145	    if (!domain) {
146	      issues.push({
147	        code: "missing_domain",
148	        field: "primary_domain",
149	        reason: "The company has no primary domain.",
150	      });
151	    }
152	
153	    const host = normalizeDomain(raw.website ?? "");
154	    if (host && isJunkHost(host)) {
155	      issues.push({
156	        code: "junk_website",
157	        field: "website",
158	        reason: `The website points to ${host}, a messaging, link-shortener or social page rather than a company site.`,
159	      });
160	    }
161	
162	    if (!linkedin) {
163	      issues.push({
164	        code: "missing_linkedin",
165	        field: "professional_network_url",
166	        reason: "The company has no LinkedIn page.",
167	      });
168	    }
169	
170	    let isLaterDuplicate = false;
171	    const key = duplicateKey(raw);
172	    if (key !== undefined) {
173	      const keptId = firstSeen.get(key);
174	      if (keptId === undefined) {
175	        firstSeen.set(key, raw.crustdata_company_id);
176	      } else {
177	        isLaterDuplicate = true;
178	        const viaDomain = key.startsWith("domain:");
179	        issues.push({
180	          code: "duplicate_domain",
181	          field: viaDomain ? "primary_domain" : "professional_network_url",
182	          reason: viaDomain
183	            ? `Another company (id ${keptId}) already uses the domain ${domain}.`
184	            : `Another company (id ${keptId}) already uses the LinkedIn page ${linkedin}.`,
185	          related_company_id: keptId,
186	        });
187	      }
188	    }
189	
190	    issues.push(...sizeIssues(raw));
191	
192	    let status: ValidationStatus;
193	    if ((noName && !domain && !linkedin) || isLaterDuplicate) {
194	      status = "rejected";
195	    } else if (issues.length > 0) {
196	      status = "flagged";
197	    } else {
198	      status = "valid";
199	    }
200	    return { status, issues };
201	  });
202	}
