// Builds facts from a raw company. Pure and deterministic: no network, no
// randomness, no mutation of the inputs. Statuses are set here by code only;
// this module never creates a fact with provider "model".

import type {
  AnyFact,
  Fact,
  FactSource,
  RawCompany,
  Validation,
  ValidationIssue,
} from "../types";
import { normalizeDomain } from "./normalize";
import { parseEmployeeRange } from "./validation";

type CrustProvider = "crustdata" | "fixture";

// Issue codes that make the fact on the issue's field uncertain.
const UNCERTAIN_CODES: ReadonlySet<string> = new Set([
  "junk_website",
  "size_headcount_mismatch",
]);

function nonEmptyText(value: unknown): value is string {
  return typeof value === "string" && value.trim() !== "";
}

function finiteNumber(value: unknown): value is number {
  return typeof value === "number" && Number.isFinite(value);
}

export function buildFacts(
  raw: RawCompany,
  validation: Validation,
  provider: CrustProvider,
): readonly AnyFact[] {
  if (validation.status === "rejected") return [];

  const recordId = String(raw.crustdata_company_id);
  const source: FactSource = {
    provider,
    operation: raw.source === "enrich" ? "company_enrich" : "company_search",
    record_id: recordId,
    retrieved_at: raw.retrieved_at,
  };

  const issueByField = new Map<string, ValidationIssue>();
  for (const issue of validation.issues) {
    if (UNCERTAIN_CODES.has(issue.code) && !issueByField.has(issue.field)) {
      issueByField.set(issue.field, issue);
    }
  }

  const facts: AnyFact[] = [];
  const byField = new Map<string, AnyFact>();

  const add = (field: string, value: unknown, claim: string): void => {
    const issue = issueByField.get(field);
    const fact: Fact<unknown> = {
      id: `${recordId}:${field}`,
      value,
      claim: issue ? `${claim} (uncertain: ${issue.reason})` : claim,
      field,
      source,
      status: issue ? "uncertain" : "given",
    };
    facts.push(fact);
    byField.set(field, fact);
  };

  const text = (field: string, value: unknown, label: string): void => {
    if (nonEmptyText(value)) add(field, value, `${label} is ${value}`);
  };

  text("name", raw.name, "Company name");
  text("primary_domain", raw.primary_domain, "Primary domain");
  text("website", raw.website, "Website");
  text(
    "professional_network_url",
    raw.professional_network_url,
    "LinkedIn page",
  );
  text("employee_count_range", raw.employee_count_range, "Employee count range");
  text("industry", raw.industry, "Industry");
  text("description", raw.description, "Description");

  if (finiteNumber(raw.founded_year)) {
    add("founded_year", raw.founded_year, `Founded in ${raw.founded_year}`);
  }
  text("legal_type", raw.legal_type, "Legal type");
  if (finiteNumber(raw.latest_headcount)) {
    add(
      "latest_headcount",
      raw.latest_headcount,
      `Latest headcount is ${raw.latest_headcount}`,
    );
  }
  text("revenue_range", raw.revenue_range, "Revenue range");
  text("location.country", raw.location?.country, "Country");
  text("location.city", raw.location?.city, "City");

  if (Array.isArray(raw.specialities)) {
    const list = raw.specialities.filter(nonEmptyText);
    if (list.length > 0) {
      add("specialities", list, `Specialities are ${list.join(", ")}`);
    }
  }
  if (finiteNumber(raw.linkedin_followers)) {
    add(
      "linkedin_followers",
      raw.linkedin_followers,
      `Has ${raw.linkedin_followers} LinkedIn followers`,
    );
  }

  // Derived cross-checks: two independent, non-uncertain facts that agree.
  const usable = (field: string): AnyFact | undefined => {
    const f = byField.get(field);
    return f && f.status === "given" ? f : undefined;
  };
  const derivedSource: FactSource = {
    provider: "derived",
    retrieved_at: raw.retrieved_at,
  };

  const website = usable("website");
  const domain = usable("primary_domain");
  if (website && domain) {
    const host = normalizeDomain(String(website.value));
    if (host !== "" && host === normalizeDomain(String(domain.value))) {
      facts.push({
        id: `${recordId}:xcheck:website_domain`,
        value: host,
        claim: `Website host matches the primary domain (${host})`,
        field: "website_domain",
        source: derivedSource,
        status: "cross_checked",
        derived_from: [website.id, domain.id],
      });
    }
  }

  const headcount = usable("latest_headcount");
  const rangeFact = usable("employee_count_range");
  if (headcount && rangeFact) {
    const range = parseEmployeeRange(rangeFact.value);
    const n = headcount.value as number;
    if (range && n >= range.min && n <= range.max) {
      facts.push({
        id: `${recordId}:xcheck:headcount_in_range`,
        value: n,
        claim: `Headcount ${n} is within the employee count range ${String(rangeFact.value)}`,
        field: "headcount_in_range",
        source: derivedSource,
        status: "cross_checked",
        derived_from: [headcount.id, rangeFact.id],
      });
    }
  }

  return facts;
}

import { describe, expect, it } from "vitest";
import { buildFacts } from "../src/core/data/facts";
import { validateCompanies } from "../src/core/data/validation";
import { FIXTURE_COMPANIES } from "../src/core/fixtures/companies";
import type { RawCompany } from "../src/core/types";

const validations = validateCompanies(FIXTURE_COMPANIES);

function build(id: number) {
  const i = FIXTURE_COMPANIES.findIndex((c) => c.crustdata_company_id === id);
  return buildFacts(FIXTURE_COMPANIES[i], validations[i], "fixture");
}

describe("buildFacts", () => {
  it("gives facts for a clean record", () => {
    const facts = build(1001);
    const range = facts.find((f) => f.id === "1001:employee_count_range");
    expect(range).toMatchObject({
      value: "51-200",
      claim: "Employee count range is 51-200",
      status: "given",
      field: "employee_count_range",
      source: {
        provider: "fixture",
        operation: "company_enrich",
        record_id: "1001",
        retrieved_at: "2026-01-15T09:00:00Z",
      },
    });
    expect(facts.find((f) => f.id === "1001:name")?.status).toBe("given");
    // Empty logo and absent optional fields produce no facts.
    expect(facts.some((f) => f.field === "logo")).toBe(false);
    expect(facts.some((f) => f.field === "description")).toBe(false);
    expect(facts.some((f) => f.source.provider === "model")).toBe(false);
  });

  it("uses company_search for search records", () => {
    const raw: RawCompany = { ...FIXTURE_COMPANIES[0], source: "search" };
    const facts = buildFacts(raw, { status: "valid", issues: [] }, "crustdata");
    expect(facts[0].source).toMatchObject({
      provider: "crustdata",
      operation: "company_search",
    });
  });

  it("marks the website uncertain on a junk website", () => {
    const facts = build(1003);
    const site = facts.find((f) => f.id === "1003:website");
    expect(site?.status).toBe("uncertain");
    expect(site?.claim).toContain("wa.link");
    expect(facts.some((f) => f.id.includes("xcheck:website_domain"))).toBe(false);
  });

  it("marks headcount uncertain on a size mismatch", () => {
    const facts = build(1008);
    const hc = facts.find((f) => f.id === "1008:latest_headcount");
    expect(hc?.status).toBe("uncertain");
    expect(hc?.claim).toContain("outside the listed size range");
    expect(facts.some((f) => f.id.includes("headcount_in_range"))).toBe(false);
  });

  it("marks revenue uncertain on implausible revenue per employee", () => {
    const facts = build(1009);
    expect(facts.find((f) => f.id === "1009:revenue_range")?.status).toBe(
      "uncertain",
    );
  });

  it("cross-checks only when both facts agree", () => {
    const clean = build(1001);
    const web = clean.find((f) => f.id === "1001:xcheck:website_domain");
    expect(web).toMatchObject({
      status: "cross_checked",
      source: { provider: "derived" },
      derived_from: ["1001:website", "1001:primary_domain"],
    });
    const size = clean.find((f) => f.id === "1001:xcheck:headcount_in_range");
    expect(size?.derived_from).toEqual([
      "1001:latest_headcount",
      "1001:employee_count_range",
    ]);

    // Website host differs from the domain: no website cross-check.
    const raw: RawCompany = {
      ...FIXTURE_COMPANIES[0],
      website: "https://other.example",
    };
    const facts = buildFacts(raw, { status: "valid", issues: [] }, "fixture");
    expect(facts.some((f) => f.id.endsWith("xcheck:website_domain"))).toBe(false);
  });

  it("returns an empty array for rejected records", () => {
    expect(validations[4].status).toBe("rejected");
    expect(build(1005)).toEqual([]);
  });

  it("builds optional enrichment facts", () => {
    const raw: RawCompany = {
      ...FIXTURE_COMPANIES[0],
      description: "Makes widgets",
      founded_year: 2010,
      location: { country: "Ireland", city: "" },
      specialities: ["a", "", "b"],
      linkedin_followers: 5,
    };
    const facts = buildFacts(raw, { status: "valid", issues: [] }, "fixture");
    const ids = facts.map((f) => f.id);
    expect(ids).toContain("1001:description");
    expect(ids).toContain("1001:founded_year");
    expect(ids).toContain("1001:location.country");
    expect(ids).not.toContain("1001:location.city");
    expect(facts.find((f) => f.id === "1001:specialities")?.value).toEqual([
      "a",
      "b",
    ]);
  });

  it("is deterministic with unique ids", () => {
    const a = build(1001);
    const b = build(1001);
    expect(a).toEqual(b);
    expect(new Set(a.map((f) => f.id)).size).toBe(a.length);
  });

  it("does not mutate its inputs", () => {
    const raw: RawCompany = JSON.parse(JSON.stringify(FIXTURE_COMPANIES[7]));
    const validation = JSON.parse(JSON.stringify(validations[7]));
    const rawCopy = JSON.parse(JSON.stringify(raw));
    const validationCopy = JSON.parse(JSON.stringify(validation));
    buildFacts(raw, validation, "fixture");
    expect(raw).toEqual(rawCopy);
    expect(validation).toEqual(validationCopy);
  });
});

